import math

def E(n):
    # E(n) = 3 * ((n+2)! + 1) / (2*n - 1)
    numerator = 3 * (math.factorial(n + 2) + 1)
    denominator = 2 * n - 1

    if denominator == 0:
        return None # Should not happen for integer n

    # We check if the division results in an integer
    if numerator % denominator == 0:
        return numerator // denominator
    else:
        return "Not Integer"

results = {}
for n in range(16):
    results[n] = E(n)

print("n | E(n) calculation | Result (Integer or Not Integer)")
print("-" * 50)
for n in range(16):
    result = results[n]
    if isinstance(result, int):
        print(f"{n:2} | {result} | Integer")
    else:
        print(f"{n:2} | {result} | Not Integer")

