import math

def calculate_E(n):
    # Handle the case where the denominator is zero, although 2n-1 = 0 means n=0.5, which is not a non-negative integer.
    # For n=0, 2n-1 = -1.
    if 2 * n - 1 == 0:
        return None # Should not happen for non-negative integers n

    try:
        numerator = 3 * (math.factorial(n + 2) + 1)
        denominator = 2 * n - 1

        # Check if the division results in an integer
        if numerator % denominator == 0:
            return numerator // denominator
        else:
            return None
    except OverflowError:
        # Factorials grow extremely fast, but Python handles large integers automatically.
        # This is mostly a safeguard.
        return None

solutions = []
print("--- Verification up to n=20 ---")
for n in range(21):
    result = calculate_E(n)
    if result is not None:
        print(f"n={n}: E(n) = {result} (Integer solution)")
        solutions.append(n)
    else:
        print(f"n={n}: E(n) is not an integer.")

print("\nFinal list of integer solutions found in [0, 20]:", solutions)

